// Code generated by `cargo run -p codegen` — DO NOT EDIT
// Quantity: VitaminA

#![cfg(feature = "misc")]
#![allow(
    clippy::excessive_precision,
    clippy::unreadable_literal,
    clippy::double_parens,
    unused_parens
)]

use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use qty::*;

#[test]
fn international_units() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(
            VitaminA::from_international_units(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x;
        assert_close(
            VitaminA::from_base(base).as_international_units(),
            back,
            F64_TOL,
        );
        assert_close(
            VitaminA::from_international_units(v).as_international_units(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            VitaminA::from_international_units(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            VitaminA::from_base(base as f32).as_international_units() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn base_unit_expression() {
    let info = <VitaminA<f64> as Quantity>::INFO;
    let expr = <VitaminA<f64> as Quantity>::BASE_UNIT_EXPR;
    let parsed = UnitExpr::parse("IU")
        .ok()
        .filter(|e| e.dimensions == info.dimensions);
    let from_data: Option<f64> = None;
    if let (Some(parsed), Some(size)) = (parsed, from_data) {
        assert_close(parsed.factor, size, F64_TOL);
    }
    match parsed {
        Some(parsed) => assert_eq!(expr, Some(parsed)),
        None => assert_eq!(expr.map(|e| e.factor), from_data),
    }
    if let Some(expr) = expr {
        assert_eq!(expr.dimensions, info.dimensions);
    }
}

#[test]
fn fixed_units() {
    check_fixed::<unit::vitamin_a::InternationalUnit>();
    check_fixed_rescale::<unit::vitamin_a::InternationalUnit>();
}

#[test]
fn unit_expressions_agree() {
    super::check_unit_exprs::<VitaminA>(VitaminA::new);
}

#[test]
fn unit_metadata() {
    let info = VitaminA::<f64>::INFO;
    assert_eq!(info.name, "VitaminA");
    assert_eq!(info.units.len(), VitaminAUnit::ALL.len());
    for (&unit, unit_info) in VitaminAUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, VitaminAUnit::InternationalUnit.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        VitaminA::new(v, VitaminAUnit::InternationalUnit),
        VitaminA::from_international_units(v)
    );
    assert_eq!(
        VitaminA::from_base(v).convert_to(VitaminAUnit::InternationalUnit),
        VitaminA::from_base(v).as_international_units()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [VitaminA; 1] =
        [VitaminA::const_new(1234.5, VitaminAUnit::InternationalUnit)];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(VitaminAUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            VitaminA::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in VitaminAUnit::ALL {
            assert_eq!(
                VitaminA::const_new(v, unit).as_base().to_bits(),
                VitaminA::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = VitaminA::from_base(v);
        let auto = q.auto_unit();
        assert_close(VitaminA::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in VitaminAUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        VitaminA::from_base(0.0).auto_unit().unit,
        VitaminAUnit::InternationalUnit
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "IU".parse::<VitaminAUnit>(),
        Ok(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        format!("2.5 {}", "IU").parse::<VitaminA>(),
        Ok(VitaminA::new(2.5, VitaminAUnit::InternationalUnit))
    );
    assert_eq!(
        "1 not-a-unit".parse::<VitaminA>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn parse_every_name() {
    assert_eq!(
        VitaminAUnit::from_name("internationalunit"),
        Some(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        VitaminAUnit::from_name("international unit"),
        Some(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        VitaminAUnit::from_name("INTERNATIONAL UNIT"),
        Some(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        VitaminAUnit::from_name("internationalunits"),
        Some(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        VitaminAUnit::from_name("international units"),
        Some(VitaminAUnit::InternationalUnit)
    );
    assert_eq!(
        VitaminAUnit::from_name("INTERNATIONAL UNITS"),
        Some(VitaminAUnit::InternationalUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = VitaminA::from_base(6.0);
    let b = VitaminA::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = VitaminA::<i64>::from_base(7);
    let b = VitaminA::<i64>::from_base(2);
    assert_eq!(a + b, VitaminA::from_base(9));
    assert_eq!(a % b, VitaminA::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<VitaminA<i64>>(), VitaminA::from_base(9));
}
